UPDATE public.opta_snapshots SET
  imported_clubs = (SELECT count(*) FROM public.opta_club_ratings r WHERE r.snapshot_id = opta_snapshots.id),
  import_scope = 'Top 400 da CONMEBOL por rating + os clubes do Paulistao 2026 usados no backtest. O corte do top 400 cobre TODAS as primeiras divisoes sul-americanas sem faltar nenhum clube (conferido contra o arquivo). Fora ficam divisoes amadoras/regionais e o resto do mundo; adversario nao mapeado torna a partida inelegivel para o modelo, nao para exibicao.'
WHERE is_active;

